    pub max_receive_count: Option<MaxReceiveCount>,
}

/// A command whose parameters have passed every check that needs no queue state.
#[derive(Debug, PartialEq, Eq)]
pub enum Command<'a> {
    CreateQueue {
        name: QueueName,
        attributes: Attributes<'a>,
    },
    SetQueueAttributes {
        queue: &'a str,
        attributes: Attributes<'a>,
    },
    GetQueueAttributes {
        queue: &'a str,
    },
