        delay: Option<DelaySeconds>,
        group: Option<GroupId>,
        deduplication: Option<DeduplicationId>,
    },
    ReceiveMessage {
        queue: &'a str,
        max_messages: Option<MaxMessages>,
        visibility_timeout: Option<VisibilityTimeout>,
    },
    DeleteMessage {
        queue: &'a str,
        receipt: &'a str,
