    fn in_flight(&self, handle: ReceiptHandle, now: Instant) -> Result<usize, Error> {
        self.messages
            .iter()
            .position(|m| m.state(now) == State::InFlight && m.receipt_handle() == Some(handle))
            .ok_or_else(|| {
