    pub fn matches(&self, requested: &Requested<'_>) -> bool {
        let same_dead_letter = match (&self.dead_letter, &requested.dead_letter) {
            (None, None) => true,
            (Some(have), Some(want)) => {
                have.queue.as_str() == want.queue
