        Ok(())
    }

    pub fn change_visibility(
        &mut self,
        handle: ReceiptHandle,
        now: Instant,
        timeout: VisibilityTimeout,
    ) -> Result<(), Error> {
        let index = self.in_flight(handle, now)?;
        self.messages[index].hold = Hold::InFlight {
            handle,
            until: now.after(timeout.seconds()),
        };
        Ok(())
    }
}

