    if messages.len() >= MAX_MESSAGES_PER_QUEUE {
        return Err(Error::new(
            ErrorCode::LimitExceeded,
            format!("the queue already holds {MAX_MESSAGES_PER_QUEUE} messages"),
        ));
    }
    Ok(())
}
